"""Wire ``on_model_request`` / ``modify_model_request`` for one LLM iteration."""

from __future__ import annotations

from typing import Any, Dict, List, Optional, Sequence, Tuple

import structlog

from rasa.agents.schemas.agent_tool_schema import AgentToolSchema
from rasa.mantle.hooks.constants import POINT_MODEL_REQUEST
from rasa.mantle.hooks.exceptions import HookExecutionError
from rasa.mantle.hooks.payloads import ModelRequestPayload
from rasa.mantle.hooks.registry import HookRegistry
from rasa.mantle.hooks.runner import run_modify, run_observers
from rasa.mantle.hooks.utils import hook_identity
from rasa.mantle.llm.client import filter_per_call_model_settings
from rasa.mantle.prompts.messages import LlmMessage

structlogger = structlog.get_logger()


async def apply_model_request_hooks(
    registry: HookRegistry,
    messages: List[LlmMessage],
    tools: Optional[Sequence[AgentToolSchema]],
    *,
    iteration: int,
) -> Tuple[List[LlmMessage], Dict[str, Any]]:
    """Run ``on_model_request`` / ``modify_model_request`` for this iteration.

    Observers are scheduled without awaiting. The modify lane may rewrite
    ``messages`` and allowlisted ``model_settings``. Tool schemas, the gated
    tool-name set, credentials, and provider/model construction stay
    engine-owned — ``tool_names`` on the payload is a read-only view.

    ``model_settings`` starts empty: the engine does not seed per-call
    overrides into the payload. Hooks are the source of those keys for this
    path; filtered settings are applied only after modify returns.

    Raises:
        HookExecutionError: When the fail-closed modify hook crashes or
            times out. Unsupported control signals at this point are discarded
            by the runner (last good payload is kept; the LLM call still runs).
    """
    if (
        not registry.observers(POINT_MODEL_REQUEST)
        and registry.modifier(POINT_MODEL_REQUEST) is None
    ):
        return messages, {}

    try:
        sender_id, channel = hook_identity()
    except LookupError:
        # Live turns establish MessageTurnContext; missing context is misuse
        # (e.g. isolated unit tests). Keep the request unmodified.
        structlogger.warning(
            "mantle.hooks.model_request.skipped_no_turn_context",
        )
        return messages, {}

    payload = ModelRequestPayload(
        sender_id=sender_id,
        channel=channel,
        messages=[dict(message) for message in messages],
        tool_names=[schema.name for schema in tools or ()],
        iteration=iteration,
    )

    run_observers(registry, POINT_MODEL_REQUEST, payload)
    result = await run_modify(registry, POINT_MODEL_REQUEST, payload)

    modified = result.payload
    if not isinstance(modified, ModelRequestPayload):
        raise HookExecutionError(
            "modify_model_request returned an unexpected payload type."
        )
    # Engine-owned: ignore any returned tool_names; filter settings.
    return (
        [dict(message) for message in modified.messages],  # type: ignore[misc]
        filter_per_call_model_settings(modified.model_settings),
    )
